import math
import random

def circle_two(a, b):
    """Circle with segment ab as diameter."""
    cx, cy = (a[0] + b[0]) / 2.0, (a[1] + b[1]) / 2.0
    return (cx, cy, math.hypot(a[0] - b[0], a[1] - b[1]) / 2.0)

def circle_three(a, b, c):
    """Circumcircle of a, b, c (falls back to the longest segment if collinear)."""
    ax, ay = a
    bx, by = b
    cx, cy = c
    d = 2 * (ax * (by - cy) + bx * (cy - ay) + cx * (ay - by))
    if d == 0:  # collinear (or duplicate) points: farthest pair is the diameter
        p, q = max(((a, b), (a, c), (b, c)),
                   key=lambda pq: math.hypot(pq[0][0] - pq[1][0], pq[0][1] - pq[1][1]))
        return circle_two(p, q)
    a2, b2, c2 = ax * ax + ay * ay, bx * bx + by * by, cx * cx + cy * cy
    ux = (a2 * (by - cy) + b2 * (cy - ay) + c2 * (ay - by)) / d
    uy = (a2 * (cx - bx) + b2 * (ax - cx) + c2 * (bx - ax)) / d
    return (ux, uy, math.hypot(ux - ax, uy - ay))

def is_inside(circle, p):
    """True if point p is inside or on the circle (with a tiny tolerance)."""
    return math.hypot(p[0] - circle[0], p[1] - circle[1]) <= circle[2] + 1e-9

def minCircle(points):
    """Smallest enclosing circle, returns [x, y, r] (iterative Welzl / incremental)."""
    pts = [tuple(p) for p in points]
    if not pts:
        return [0.0, 0.0, 0.0]
    random.shuffle(pts)
    circle = (pts[0][0], pts[0][1], 0.0)
    for i in range(1, len(pts)):
        if not is_inside(circle, pts[i]):
            # pts[i] must lie on the boundary
            circle = (pts[i][0], pts[i][1], 0.0)
            for j in range(i):
                if not is_inside(circle, pts[j]):
                    # pts[i] and pts[j] must both lie on the boundary
                    circle = circle_two(pts[i], pts[j])
                    for k in range(j):
                        if not is_inside(circle, pts[k]):
                            circle = circle_three(pts[i], pts[j], pts[k])
    return list(circle)

